    if(y>=68&&y<=115){const size=30,gap=18,width=9*size+8*gap+12,start=(VW-width)/2;for(let i=0;i<9;i++){const xx=start+i*(size+gap)+(i===8?12:0);if(x>=xx&&x<=xx+size&&J.equip(chosen().key,i)){saveNow();return;}}}
